record.field:
picking = env['stock.picking'].browse(record.res_id).exists()

if not picking or picking.state != 'draft':
    raise UserError(
        'Picking %s phải ở trạng thái Draft để Confirm (state: %s).'
        % (
            picking.name if picking else record.res_id,
            picking.state if picking else 'not found',
        )
    )

picking.action_confirm()

picking = env['stock.picking'].browse(record.res_id).exists()

if not picking or picking.state == 'draft':
    raise UserError(
        'Picking %s không thay đổi trạng thái sau khi Confirm (state: %s).'
        % (
            picking.name if picking else record.res_id,
            picking.state if picking else 'not found',
        )
    )
